/**
 * Compiles a parsed `Program` into a `CompiledGame`: validated,
 * inheritance-resolved element and interaction definitions.
 *
 * Input: `Program` AST from the parser. Output: `CompiledGame` with one
 * `CompiledElement` per element (fields parent-first, methods inherited with
 * child overrides) and interactions in source order. Bodies stay AST for the
 * interpreter to execute later; no runtime instances are created here.
 * Invalid programs (duplicates, unknown parents, cycles, bad interactions)
 * throw an `Error`.
 */
import type {
    ElementDef,
    ElementFuncDef,
    ElementVarDef,
    Expression,
    Identifier,
    InteractionDef,
    Program,
} from '../../ast/ast';

import type { CompiledElement, CompiledGame } from '../contracts';

export const ROOT_ELEMENT_NAME = 'Element';

export function buildGame(program: Program): CompiledGame {
    const definitions = registerElements(program);
    const elements = resolveElements(definitions);
    validateInteractions(program.interactionDefs, elements);

    return {
        elements,
        interactions: program.interactionDefs,
    };
}

function registerElements(program: Program): Map<string, ElementDef> {
    const definitions = new Map<string, ElementDef>();
    for (const def of program.elementDefs) {
        const name = def.name.value;
        if (name === ROOT_ELEMENT_NAME) {
            throw new Error(`Cannot redefine reserved root element "${ROOT_ELEMENT_NAME}".`);
        }
        if (definitions.has(name)) {
            throw new Error(`Duplicate element definition "${name}".`);
        }
        definitions.set(name, def);
    }
    return definitions;
}

function resolveElements(
    definitions: ReadonlyMap<string, ElementDef>,
): Map<string, CompiledElement> {
    const elements = new Map<string, CompiledElement>();
    elements.set(ROOT_ELEMENT_NAME, rootElement());

    for (const name of definitions.keys()) {
        resolveElement(name, definitions, elements, []);
    }

    return elements;
}

function resolveElement(
    name: string,
    definitions: ReadonlyMap<string, ElementDef>,
    resolved: Map<string, CompiledElement>,
    stack: readonly string[],
): CompiledElement {
    const cached = resolved.get(name);
    if (cached) {
        return cached;
    }
    if (stack.includes(name)) {
        throw new Error(`Inheritance cycle: ${[...stack, name].join(' -> ')}`);
    }
    const def = definitions.get(name);
    if (!def) {
        throw new Error(`Unknown parent element "${name}".`);
    }
    const parent = resolveElement(
        def.parent?.value ?? ROOT_ELEMENT_NAME,
        definitions,
        resolved,
        [...stack, name],
    );
    const compiled: CompiledElement = {
        name,
        abstract: def.abstract,
        fieldInitializers: resolveFields(def, parent),
        methods: resolveMethods(def, parent),
        /** Start Code Generated by Claude on 2026-11-25 */
        ancestors: [parent.name, ...(parent.ancestors ?? [])],
        /** End Code Generated by Claude on 2026-11-25 */
    };
    resolved.set(name, compiled);

    return compiled;
}

function resolveFields(
    def: ElementDef,
    parent: CompiledElement,
): readonly ElementVarDef[] {
    return [...parent.fieldInitializers, ...def.varDefs];
}

function resolveMethods(
    def: ElementDef,
    parent: CompiledElement,
): Map<string, ElementFuncDef> {
    const methods = new Map<string, ElementFuncDef>(parent.methods);
    for (const funcDef of def.funcDefs) {
        methods.set(funcDef.name.value, funcDef);
    }
    return methods;
}

function validateInteractions(
    interactions: readonly InteractionDef[],
    elements: ReadonlyMap<string, CompiledElement>,
): void {
    for (const interaction of interactions) {
        if (!elements.has(interaction.element1.value)) {
            throw new Error(`Unknown element "${interaction.element1.value}" in interaction.`);
        }
        if (!elements.has(interaction.element2.value)) {
            throw new Error(`Unknown element "${interaction.element2.value}" in interaction.`);
        }
        if (interaction.element1Binding.value === interaction.element2Binding.value) {
            throw new Error(`Duplicate interaction binding "${interaction.element1Binding.value}".`);
        }
    }
}

function rootElement(): CompiledElement {
    return {
        name: ROOT_ELEMENT_NAME,
        abstract: true,
        fieldInitializers: [
            makeField('position_x', { type: 'NumberLiteral', value: 0 }),
            makeField('position_y', { type: 'NumberLiteral', value: 0 }),
            makeField('color', null),
        ],
        methods: new Map<string, ElementFuncDef>(),
    };
}

function makeField(name: string, value: Expression | null): ElementVarDef {
    return {
        type: 'ElementVarDef',
        varName: makeIdentifier(name),
        value,
    };
}

function makeIdentifier(value: string): Identifier {
    return {
        type: 'Identifier',
        value,
    };
}
